 m.AllBots();Check(m.StartMatch(),"rematch resets eight competitors and all claims");Check(m.Round==1&&m.Remaining==8&&m.TotalCaptures==0&&m.secured.All(s=>s<0),"no stale elimination or capture on rematch");while(m.Phase==ParkingPhase.Countdown)yield return null;yield return new WaitForSeconds(.3f);m.settings.music=0;m.settings.Save(false);yield return null;Check(m.music.volume==0&&m.Phase==ParkingPhase.Music,"muted music retains strong visible phase and legal simulation");m.settings.music=savedMusic;m.settings.Save(false);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1280,800),new Vector2Int(1024,768),new Vector2Int(2560,1080)}){Check(Capture(size.x,size.y),"all truck and bay boundaries fit camera-only "+size.x+"x"+size.y);}foreach(var text in new[]{m.menus.header,m.menus.status,m.menus.standings}){text.ForceMeshUpdate();Check(!text.isTextOverflowing,"long-name compact HUD fits "+text.name);}m.SetupScreen();RestorePrefs();SportsNavigation.FrontEnd();yield return null;yield return null;var f=FindAnyObjectByType<SportsFrontEnd>();f.Action("cataloguenext");Check(f.catalogue.cards.Length>=16&&f.catalogue.cards[15].activeInHierarchy,"playable parking appears on second catalogue page");Check(f.music!=null,"front exposes persisted music-volume control");f.Action("parking");yield return null;yield return null;m=FindAnyObjectByType<ParkingMatch>();Check(m!=null,"collection loads saved parking scene");m.AllBots();Check(m.StartMatch(),"returned parking match starts");m.SetupScreen();log.AppendLine("ERRORS="+errors+". Rule fixtures, real PhysX body contacts, virtual devices, camera-only renders and native TMP layout. No hardware or human validation.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("PARKING_FOCUSED_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
