 bool Fits(Camera camera,Bounds bounds){for(int i=0;i<8;i++){var p=camera.WorldToViewportPoint(bounds.center+Vector3.Scale(bounds.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));if(p.z<=0||p.x<-.01f||p.x>1.01f||p.y<-.01f||p.y>1.01f)return false;}return true;}
